package ca.mcgill.ecse321.ecse321project03.repository;

import org.springframework.data.repository.CrudRepository;

import ca.mcgill.ecse321.ecse321project03.model.Cart;

public interface CartRepository extends CrudRepository<Cart, Integer> {

    /**
     * Find a cart by its associated account. Auto-generated by Spring Data JPA from method name.
     */
    Cart findByAccount_Id(int accountId);
}
